package com.stacklab.config;
import com.stacklab.security.JwtAuthFilter; import org.springframework.context.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig{
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain security(HttpSecurity http,JwtAuthFilter jwt,com.fasterxml.jackson.databind.ObjectMapper mapper)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((r,x,ex)->{x.setStatus(401);x.setContentType("application/json");mapper.writeValue(x.getOutputStream(),java.util.Map.of("timestamp",java.time.Instant.now(),"status",401,"error","Unauthorized","message","Authentication required","path",r.getRequestURI()));}).accessDeniedHandler((r,x,ex)->{x.setStatus(403);x.setContentType("application/json");mapper.writeValue(x.getOutputStream(),java.util.Map.of("timestamp",java.time.Instant.now(),"status",403,"error","Forbidden","message","Access denied","path",r.getRequestURI()));})).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/swagger-ui.html","/swagger-ui/**","/v3/api-docs.yaml","/v3/api-docs/**","/h2-console/**").permitAll().anyRequest().authenticated()).headers(h->h.frameOptions(f->f.sameOrigin())).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build();}
}
